import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-09-14（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-09-14.md","filePath":"topics/biomedicine/science-daily-2026-09-14.md"}'),l={name:"topics/biomedicine/science-daily-2026-09-14.md"};function r(n,e,c,s,u,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-09-14-生物医学" tabindex="-1">科学日报 · 2026-09-14（生物医学） <a class="header-anchor" href="#科学日报-·-2026-09-14-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-09-14（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> — 第25期</p></blockquote><hr><h2 id="pcsk9-碱基编辑与人胚胎发育-高效修复但暂不宜临床-nature" tabindex="-1">PCSK9 碱基编辑与人胚胎发育：高效修复但暂不宜临床（Nature） <a class="header-anchor" href="#pcsk9-碱基编辑与人胚胎发育-高效修复但暂不宜临床-nature" aria-label="Permalink to &quot;PCSK9 碱基编辑与人胚胎发育：高效修复但暂不宜临床（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ DOI: 10.1038/s41586-026-11118-x</p></blockquote><ul><li>Cas9 双链断裂在人类胚胎中具遗传毒性（非整倍体 + 大片段缺失）；本文首次系统比较碱基编辑器在人类胚胎 PCSK9 与 HBG 位点的<strong>缺口/错配修复结局</strong>。</li><li>以蛋白质形式（非 mRNA）递送 ABE8e-V106W：可编辑<strong>所有</strong> PCSK9 等位基因，支持发育至囊胚、建立纯合编辑干细胞系，<strong>无插入缺失</strong>，仅偶发靶向染色体断裂/异常。</li><li>局限：旁观者与脱靶编辑呈<strong>嵌合</strong>；mRNA 递送因非向导依赖的脱氨酶活性导致频繁胚胎停滞。</li><li>洞察：碱基编辑器损伤可被高效修复（异于 Cas9 断裂），但残余基因组/发育风险<strong>当前仍排除生殖临床</strong>——是&quot;CRISPR 生殖编辑冷静评估&quot;的关键实证，衔接本主题降胆固醇/基因修复主线。</li></ul><h2 id="gpn-star-系统发育感知基因组语言模型预测全基因组功能约束-nature" tabindex="-1">GPN-Star：系统发育感知基因组语言模型预测全基因组功能约束（Nature） <a class="header-anchor" href="#gpn-star-系统发育感知基因组语言模型预测全基因组功能约束-nature" aria-label="Permalink to &quot;GPN-Star：系统发育感知基因组语言模型预测全基因组功能约束（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ DOI: 10.1038/s41586-026-11005-5</p></blockquote><ul><li>标准基因组语言模型（借用 NLP 结构）常需巨大算力且在预测上不及经典进化模型。</li><li>GPN-Star 提出<strong>系统发育感知架构</strong>：显式利用全基因组比对 + 物种树建模进化关系，在脊椎/哺乳/灵长类时间尺度预训练。</li><li>人类编码区与非编码区的变异效应预测全达 SOTA；致病变异优先排序与精细定位 GWAS 变异显著更优，复杂性状遗传力富集更强、罕见变异关联检验功效提升；并扩展至鼠/鸡/果蝇/线虫五个模式物种。</li><li>洞察：&quot;进化信息（比对+树）+ 语言模型&quot;是改进人类遗传学分析的可行配方——把<strong>系统发育先验</strong>内建进表征。</li></ul><h2 id="家族内祖先效应-墨西哥人群复杂性状的无偏因果估计-nature" tabindex="-1">家族内祖先效应：墨西哥人群复杂性状的无偏因果估计（Nature） <a class="header-anchor" href="#家族内祖先效应-墨西哥人群复杂性状的无偏因果估计-nature" aria-label="Permalink to &quot;家族内祖先效应：墨西哥人群复杂性状的无偏因果估计（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ DOI: 10.1038/s41586-026-11039-9</p></blockquote><ul><li>人群间类型差异多大源于遗传，对多数复杂性状未知；人群层面对比受祖先-环境相关混淆，多基因预测易产生偏倚。</li><li>用墨西哥城前瞻性研究：52,583 无亲缘个体 + 17,627 家庭的 39,714 亲属，评估遗传祖先与 15 种复杂性状。</li><li>人群层面（较欧洲祖先）、美洲原住民祖先：身高 −1.98 s.d.、2 型糖尿病 logOR 1.73；<strong>家庭内</strong>则 −1.51 s.d. 与 logOR 5.13，且获性状相关位点等位基因计数差异与选择信号支持。</li><li>洞察：教育程度等人群显著关联在家庭内<strong>并无</strong>祖先效应 → 指向环境/混杂。家庭内分析是&quot;祖先-环境去混淆&quot;的因果性设计。</li></ul><h2 id="gen-compas-生成式俘获门控路径采样破解分子转变时间尺度-nature" tabindex="-1">Gen-COMPAS：生成式俘获门控路径采样破解分子转变时间尺度（Nature） <a class="header-anchor" href="#gen-compas-生成式俘获门控路径采样破解分子转变时间尺度-nature" aria-label="Permalink to &quot;Gen-COMPAS：生成式俘获门控路径采样破解分子转变时间尺度（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ DOI: 10.1038/s41586-026-11025-1</p></blockquote><ul><li>蛋白折叠、变构、膜转运等分子转变天然稀有，超出标准分子动力学可达尺度；增强采样昂贵且依赖任意参数/变量引入偏倚。</li><li>Gen-COMPAS = 去噪扩散模型（生成结构合理的<strong>中间靶点</strong>）+ committor（匹配者）过滤（识别<strong>过渡态</strong>）；从中间点短时长无偏模拟即得过渡区系综。</li><li>迷你蛋白 → 五聚体配体门控离子通道：仅凭已知端点结构即可恢复匹配者、过渡态与自由能景观，无需预定义反应坐标或先验机理。</li><li>洞察：把 AI 生成模型引入生物分子机制模拟，是&quot;AI for Science&quot;在计算化学/生物物理的可计算收敛。</li></ul>',15)])])}const h=t(l,[["render",r]]);export{p as __pageData,h as default};
